.github/workflows/edge.yml.content:
name: edge
on: {push: {branches: [main]}}
permissions: {contents: read}
concurrency: {group: "hiroba-release-${{ github.repository }}", cancel-in-progress: false}
jobs:
  edge:
    uses: 7K-Hiroba/workflows/.github/workflows/edge.yml@ae4be82b95cee92eecd8d87ba55204dea750c7e1 # v1.1.0
    with: {root: .}
    permissions: {contents: write, packages: write, id-token: write, attestations: write, actions: read, artifact-metadata: write}

.github/workflows/release-please.yml.content:
name: release-please
on: {push: {branches: [main]}}
permissions: {contents: read}
jobs:
  propose:
    uses: 7K-Hiroba/workflows/.github/workflows/release-please.yml@ae4be82b95cee92eecd8d87ba55204dea750c7e1 # v1.1.0
    with: {root: ., app-id: "${{ vars.HIROBA_RELEASE_APP_ID }}"}
    secrets:
      release-private-key: "${{ secrets.HIROBA_RELEASE_PRIVATE_KEY }}"
    permissions: {contents: write, pull-requests: write}

.github/workflows/release.yml.content:
name: release
on:
  push: {branches: [main]}
  workflow_dispatch:
    inputs: {repair_tag: {required: false, type: string}}
permissions: {contents: read}
concurrency: {group: "hiroba-release-${{ github.repository }}", cancel-in-progress: false}
jobs:
  release:
    uses: 7K-Hiroba/workflows/.github/workflows/release.yml@ae4be82b95cee92eecd8d87ba55204dea750c7e1 # v1.1.0
    with: {root: ., repair_tag: "${{ inputs.repair_tag }}", app-id: "${{ vars.HIROBA_RELEASE_APP_ID }}"}
    secrets:
      release-private-key: "${{ secrets.HIROBA_RELEASE_PRIVATE_KEY }}"
    permissions: {contents: write, packages: write, id-token: write, attestations: write, actions: read, artifact-metadata: write}

.github/workflows/runtime-smoke.yml.content:
name: runtime smoke
on: {pull_request: {branches: [main]}}
permissions: {contents: read}
jobs:
  smoke:
    uses: 7K-Hiroba/workflows/.github/workflows/test-runtime-smoke.yml@ae4be82b95cee92eecd8d87ba55204dea750c7e1 # v1.1.0
    with: {root: ., mode: local, profile: ci}

.github/workflows/test-packages.yml.content:
name: package tests
on: {pull_request: {branches: [main]}}
permissions: {contents: read}
jobs:
  test:
    uses: 7K-Hiroba/workflows/.github/workflows/test-packages.yml@ae4be82b95cee92eecd8d87ba55204dea750c7e1 # v1.1.0
    with: {root: .}

.github/workflows/validate.yml.content:
name: validate
on: {pull_request: {branches: [main]}, merge_group: {}}
permissions: {contents: read}
jobs:
  validate:
    uses: 7K-Hiroba/workflows/.github/workflows/validate-packages.yml@ae4be82b95cee92eecd8d87ba55204dea750c7e1 # v1.1.0
    with: {root: .}

release-please-config.json.content:
{
  "$schema": "https://raw.githubusercontent.com/googleapis/release-please/main/schemas/config.json",
  "separate-pull-requests": false,
  "include-component-in-tag": true,
  "include-v-in-tag": true,
  "tag-separator": "-v",
  "pull-request-title-pattern": "chore: release ${component} ${version}",
  "packages": {
    "packages/matrix-app": {
      "release-type": "simple",
      "changelog-path": "CHANGELOG.md",
      "bump-minor-pre-major": true,
      "bump-patch-for-minor-pre-major": true,
      "extra-files": [
        "package.yaml"
      ]
    },
    "tests/smoke": {
      "release-type": "simple",
      "changelog-path": "CHANGELOG.md",
      "bump-minor-pre-major": true,
      "bump-patch-for-minor-pre-major": true,
      "extra-files": [
        "suite.yaml"
      ],
      "component": "matrix-app-smoke"
    }
  }
}

renovate.json.content:
{
  "$schema": "https://docs.renovatebot.com/renovate-schema.json",
  "extends": ["config:recommended"],
  "pinDigests": true,
  "packageRules": [
    {
      "description": "Review trusted workflow SHAs and action updates manually",
      "matchManagers": ["github-actions"],
      "automerge": false
    },
    {
      "description": "Group reviewed non-major SDK and chart dependency updates",
      "matchUpdateTypes": ["minor", "patch", "digest", "pinDigest"],
      "groupName": "non-major dependencies",
      "automerge": false
    }
  ]
}
